import assert from 'node:assert/strict';import {pathToFileURL} from 'node:url';let input='';for await(const c of process.stdin)input+=c;const cfg=JSON.parse(input);const {chromium}=await import(pathToFileURL(cfg.module+'/index.mjs').href);const browser=await chromium.launch({headless:true,...(cfg.executable?{executablePath:cfg.executable}:{})});
try{const page=await browser.newPage();const errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('response',r=>{if(r.status()>=400)errors.push('HTTP '+r.status()+' '+new URL(r.url()).pathname)});await page.goto(cfg.url);for(const [,api,raw] of cfg.rows){const expected=JSON.parse(raw),short=api.slice(0,2),pre=page.locator(`[data-lwr="${short}"]`).filter({hasNotText:'pending'});try{await pre.waitFor({timeout:15000})}catch(e){throw new Error(`LWR ${api}: ${errors.join('; ')}`)}assert.deepEqual(JSON.parse(await pre.textContent()),expected.initial);await page.locator(`c-b11lwr${short} button[data-action=invalid]`).evaluate(e=>e.click());await page.waitForTimeout(50);assert.deepEqual(JSON.parse(await pre.textContent()),expected.invalid);}assert.deepEqual(errors,[]);}finally{await browser.close()}
